{
  "passages": [
    {
      "reference": "16.1",
      "verdict": "revise",
      "checks": {
        "complete_coverage": false,
        "no_added_claims": true,
        "names_and_negations": true,
        "lexical_fidelity": false,
        "uncertainties_disclosed": true
      },
      "findings": [
        {
          "source_quote": "ἀπ’ αὐτῆς ἑσπέρας μαθὼν",
          "english_quote": "Having learned last evening",
          "issue": "The dawn setting supports identifying the evening as the preceding evening, but the draft loses the emphasis of αὐτῆς and the temporal force of ἀπό: learning already from that very evening.",
          "suggested_revision": "Consider ‘Having learned as early as last evening’. This preserves the contextual dating while making the source’s emphasis explicit.",
          "severity": "minor"
        },
        {
          "source_quote": "ταῦτα τοῦ διακόνου λέγοντος, ἰδοὺ αὐτὸς εἰσῄει Σίμων",
          "english_quote": "While the attendant was saying this, Simon himself came in with Athenodorus and some other companions.",
          "issue": "The presentational exclamation ἰδοὺ is omitted. The source draws attention to Simon’s entrance while the announcement is still being made.",
          "suggested_revision": "Restore the presentational force, for example: ‘While the attendant was saying this, look—Simon himself was coming in with Athenodorus and some other companions.’",
          "severity": "minor"
        }
      ]
    },
    {
      "reference": "16.2",
      "verdict": "revise",
      "checks": {
        "complete_coverage": true,
        "no_added_claims": false,
        "names_and_negations": true,
        "lexical_fidelity": false,
        "uncertainties_disclosed": true
      },
      "findings": [
        {
          "source_quote": "ὡς τὰ μέγιστα ἁμαρτάνων",
          "english_quote": "as one committing the greatest sin",
          "issue": "τὰ μέγιστα qualifies the act of sinning adverbially. The draft instead identifies a singular object as ‘the greatest sin’, introducing a more specific ranking of an offense rather than preserving the source’s description of sinning to an extreme degree.",
          "suggested_revision": "Use ‘as someone sinning most grievously’ or another rendering that preserves the adverbial construction without asserting a uniquely greatest sin.",
          "severity": "minor"
        }
      ]
    },
    {
      "reference": "16.3",
      "verdict": "revise",
      "checks": {
        "complete_coverage": true,
        "no_added_claims": true,
        "names_and_negations": true,
        "lexical_fidelity": false,
        "uncertainties_disclosed": true
      },
      "findings": [
        {
          "source_quote": "ὀργῇ πεπρισμένον",
          "english_quote": "while inflamed with anger",
          "issue": "The draft replaces the cutting or sawing image with a fire image. Its note acknowledges the source image, but that disclosure does not make the substituted image faithful in the main text.",
          "suggested_revision": "Use a cutting-image rendering such as ‘while cut through by anger’. Retain the note explaining the participle’s sawing or cutting force.",
          "severity": "major"
        }
      ]
    },
    {
      "reference": "16.4",
      "verdict": "revise",
      "checks": {
        "complete_coverage": true,
        "no_added_claims": true,
        "names_and_negations": true,
        "lexical_fidelity": false,
        "uncertainties_disclosed": false
      },
      "findings": [
        {
          "source_quote": "εἰ γὰρ τῷ καταψευδομένῳ τὸ αὐτὸ λέγει, καὶ αὐτὸς ψεύδεται",
          "english_quote": "For if he says the same as the one accused of lying, he too lies.",
          "issue": "‘Accused of lying’ does not adequately represent either the middle reading, involving speaking falsely, or the passive reading, involving being falsely accused or lied about. The note mentions the passive possibility but does not preserve the middle alternative. Its rationale also confuses being falsely accused with being established as actually false.",
          "suggested_revision": "A contextual middle rendering for fresh review is: ‘For if he says the same thing as the one speaking falsely, he too is lying.’ Explain why the conditional argument favors that reading, and preserve the passive alternative, ‘the one being falsely accused’, in a note. Do not present either interpretation as uncontested.",
          "severity": "major"
        },
        {
          "source_quote": "ὁ δὲ τὸν ἕνα λέγοντα ψεύσματος ἐλέξαι ἐπαγγελλόμενος",
          "english_quote": "someone promising to convict the speaker of one God of falsehood",
          "issue": "The supplied print reads ἐλέξαι, whereas ‘convict’ treats it as corresponding to the expected ἐλέγξαι. The preceding ἐλέγξειν supports that contextual interpretation, but the draft silently passes over the printed-form issue.",
          "suggested_revision": "Add a source-quoted note recording the supplied ἐλέξαι and explaining the contextual basis for ‘convict’. Distinguish any proposed normalization to ἐλέγξαι from the actual printed reading. This is not evidence of an OCR error, and the supplied image-checked transcription need not be rejected merely because of this form.",
          "severity": "minor"
        }
      ]
    },
    {
      "reference": "16.5",
      "verdict": "revise",
      "checks": {
        "complete_coverage": false,
        "no_added_claims": true,
        "names_and_negations": true,
        "lexical_fidelity": false,
        "uncertainties_disclosed": false
      },
      "findings": [
        {
          "source_quote": "καὶ ὁμῶς ὁ Πέτρος ἔφη",
          "english_quote": "Peter nevertheless said",
          "issue": "The supplied accentuation is ὁμῶς, whose ordinary sense is ‘alike’ or ‘likewise’, rather than ὅμως, ‘nevertheless’. The draft adopts the adversative sense without discussing the printed reading or distinguishing a possible accent normalization from it.",
          "suggested_revision": "Use a source-preserving candidate such as ‘And Peter likewise said’. If an adversative interpretation is proposed instead, provide its linguistic and contextual justification and explicitly distinguish the supplied ὁμῶς from any proposed ὅμως. Do not label the verified print an OCR error.",
          "severity": "major"
        },
        {
          "source_quote": "κἀγὼ ἕνα θεὸν εἶναι λέγω",
          "english_quote": "I say that there is one God, who made heaven, earth, and everything in them.",
          "issue": "The additive force of κἀγώ, ‘I too’, is omitted. This also conceals the wording parallel with the father’s κἀγὼ λέγω in 16.4.",
          "suggested_revision": "Restore ‘I too say that there is one God, who made heaven, earth, and everything in them.’ Preserve the additive wording without inventing an explanation of whom Peter is aligning himself with.",
          "severity": "minor"
        },
        {
          "source_quote": "ἄλλον. δὲ οὔτε λέγειν οὔτε νομίζειν ἔξεστιν.",
          "english_quote": "It is not permitted to call or consider anyone else a god.",
          "issue": "The English intelligibly joins the construction across the unusual printed full stop after ἄλλον, but the draft’s source_issues remains empty. This selected-edition punctuation feature should be distinguished from a textual lacuna or an unverified transcription.",
          "suggested_revision": "Add a source-quoted note stating that the print has ‘ἄλλον. δὲ’ and that the English treats the surviving words as one construction. Do not describe the full stop as a gap, supply missing words, or claim that a corrected Greek reading has been verified.",
          "severity": "minor"
        }
      ]
    }
  ]
}
